{$ param title label="Title" default="Accordion Title" description="Visible heading on the collapsed panel." $}
{$ param panel_id label="Panel ID" default="accordion-panel" description="Unique id stem for this item (appended with random suffix in markup)." $}

<div class="ss-accordion2 w-full mx-auto border border-linework shadow mb-4 max-w-[1024px]">
  <button
    type="button"
    class="w-full flex justify-between items-center px-4 py-3 text-left font-semibold focus:outline-none focus-visible:ring focus-visible:ring-primary-action ss-accordion2-btn"
    aria-expanded="false">
    <h2 class="text-lg mb-0 text-primary">{$= title $}</h2>
    <svg class="w-5 h-5 transition-transform duration-200" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/>
    </svg>
  </button>
  <div class="px-4 py-3 hidden mx-auto ss-accordion2-panel" role="region">
    <div class="max-w-[960px]">
      {$ slot panel $}
        <p>Panel content.</p>
      {$ /slot $}
    </div>
  </div>
</div>

<script>
(function() {
  if (window.__ssAccordion2Bound) return;
  window.__ssAccordion2Bound = true;
  document.addEventListener('click', function(e) {
    var btn = e.target.closest('.ss-accordion2 .ss-accordion2-btn');
    if (!btn) return;
    var panel = btn.parentElement.querySelector('.ss-accordion2-panel');
    var expanded = btn.getAttribute('aria-expanded') === 'true';
    btn.setAttribute('aria-expanded', expanded ? 'false' : 'true');
    btn.querySelector('svg').classList.toggle('rotate-180', !expanded);
    panel.classList.toggle('hidden', expanded);
  });
})();
</script>
